import os
import hmac
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import xml.etree.ElementTree as ET
import re

app = Flask(__name__)
DATABASE = '/data/inventory.db'
SECRET = os.environ.get('HMAC_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.executescript('''
        CREATE TABLE IF NOT EXISTS products (
            id INTEGER PRIMARY KEY,
            sku TEXT UNIQUE,
            name TEXT,
            price REAL,
            quantity INTEGER
        );
        CREATE TABLE IF NOT EXISTS api_keys (
            id INTEGER PRIMARY KEY,
            key_hash TEXT,
            owner TEXT,
            permissions TEXT
        );
        INSERT OR IGNORE INTO products VALUES (1, 'WDG-001', 'Widget A', 9.99, 150);
        INSERT OR IGNORE INTO products VALUES (2, 'WDG-002', 'Widget B', 14.99, 85);
        INSERT OR IGNORE INTO api_keys VALUES (1, 'admin_hash', 'system', 'full');
    ''')
    db.commit()
    db.close()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Api-Token', '')
        if len(token) < 8:
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/api/products/search')
@require_auth
def search_products():
    """Search products by name or SKU with optional sorting."""
    query = request.args.get('q', '')
    sort_field = request.args.get('sort', 'name')
    sort_dir = request.args.get('dir', 'ASC')

    # Validate sort direction
    if sort_dir.upper() not in ('ASC', 'DESC'):
        sort_dir = 'ASC'

    # Build query - sort_field is validated against allowed columns
    allowed_sorts = {'name', 'price', 'quantity', 'sku'}
    if sort_field not in allowed_sorts:
        sort_field = 'name'

    # Search uses LIKE with user input directly interpolated
    sql = f"SELECT id, sku, name, price, quantity FROM products WHERE name LIKE '%{query}%' OR sku LIKE '%{query}%' ORDER BY {sort_field} {sort_dir}"

    try:
        db = get_db()
        results = db.execute(sql).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return jsonify({'error': 'search failed', 'detail': str(e)}), 500

@app.route('/api/products/bulk-update', methods=['POST'])
@require_auth
def bulk_update():
    """Bulk update product quantities from XML payload."""
    content_type = request.content_type or ''
    if 'xml' not in content_type.lower():
        return jsonify({'error': 'content-type must be application/xml'}), 415

    try:
        # Parse XML - note: ET.fromstring is safe against XXE in Python 3.8+
        root = ET.fromstring(request.data)
        updates = []
        for item in root.findall('.//product'):
            sku = item.get('sku', '')
            qty = item.get('quantity', '0')
            if sku and qty.isdigit():
                updates.append((int(qty), sku))

        db = get_db()
        db.executemany('UPDATE products SET quantity = ? WHERE sku = ?', updates)
        db.commit()
        return jsonify({'updated': len(updates)})
    except ET.ParseError:
        return jsonify({'error': 'invalid xml'}), 400

@app.route('/api/products/report')
@require_auth
def generate_report():
    """Generate filtered report with custom grouping."""
    group_by = request.args.get('group', '')
    having = request.args.get('having', '')
    min_price = request.args.get('min_price', '0')

    # Attempt numeric validation for min_price
    try:
        min_price_val = float(min_price)
    except ValueError:
        min_price_val = 0

    # group_by is directly interpolated - SQL injection vector
    if group_by:
        sql = f"SELECT {group_by}, COUNT(*) as cnt, AVG(price) as avg_price FROM products WHERE price >= {min_price_val} GROUP BY {group_by}"
        if having:
            sql += f" HAVING {having}"
    else:
        sql = f"SELECT * FROM products WHERE price >= {min_price_val}"

    try:
        db = get_db()
        results = db.execute(sql).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        return jsonify({'error': 'report failed', 'detail': str(e)}), 500

